select jsonb_build_object(
'captured_at', now(),
'runs', (select jsonb_agg(jsonb_build_array(id,period_start,valuation_date,overall_status,valuation_context_source,source_trigger,finished_at) order by id) from costing.costing_refresh_run where id>=110),
'run_count', (select count(*) from costing.costing_refresh_run),
'run_status_counts', (select jsonb_object_agg(overall_status,n) from (select overall_status,count(*) n from costing.costing_refresh_run group by 1) x),
'designations', (select jsonb_agg(to_jsonb(d) - 'note' order by id) from costing.costing_run_designation d),
'periods', (select jsonb_agg(jsonb_build_array(period_start,status,valuation_date,valuation_date_status,valuation_date_source,locked_at,closed_at) order by period_start) from costing.cost_periods),
'fingerprints', (select jsonb_agg(jsonb_build_array(id,refresh_run_id,purpose,captured_at,fingerprint->>'algorithm',fingerprint->>'version',(select count(*) from jsonb_object_keys(fingerprint->'tables')) ) order by id) from costing.costing_run_fingerprint),
'fp_keys_sample', (select jsonb_agg(k) from (select jsonb_object_keys(fingerprint) k from costing.costing_run_fingerprint where id=13) z),
'verify_122', (select jsonb_agg(jsonb_build_array(t.*)) from costing.fn_verify_run_fingerprint(122) t where not matches),
'verify_128', (select jsonb_agg(jsonb_build_array(t.*)) from costing.fn_verify_run_fingerprint(128) t where not matches),
'verify_122_n', (select count(*) from costing.fn_verify_run_fingerprint(122)),
'rebaseline', (select jsonb_agg(jsonb_build_array(id,refresh_run_id,fingerprint_id,reference_fingerprint_id,excluded_columns,approval_reference,rebaselined_at,evidence) order by id) from costing.costing_run_fingerprint_rebaseline),
'cron', (select jsonb_agg(jsonb_build_array(jobid,jobname,schedule,active) order by jobid) from cron.job),
'cron_6061_last', (select jsonb_agg(jsonb_build_array(jobid,status,start_time) order by start_time desc) from (select jobid,status,start_time from cron.job_run_details where jobid in (60,61) order by start_time desc limit 4) z),
'switches', jsonb_build_object(
  'plant_aware_load_switch', (select jsonb_agg(to_jsonb(s)) from costing.plant_aware_load_switch s),
  'batch_true_standard_switch', (select jsonb_agg(to_jsonb(s)) from costing.batch_true_standard_switch s),
  'qc_batch_true_switch', (select jsonb_agg(to_jsonb(s)) from costing.qc_batch_true_switch s),
  'route_load_scaling_switch', (select jsonb_agg(to_jsonb(s)) from costing.route_load_scaling_switch s),
  'cost_head_policy_switch', (select jsonb_agg(to_jsonb(s)) from costing.cost_head_policy_switch s),
  'costing_sales_feed_switch', (select jsonb_agg(to_jsonb(s)) from costing.costing_sales_feed_switch s)),
'capacity', jsonb_build_object(
  'profile_rows', (select count(*) from costing.plant_capacity_profile),
  'profile_machines', (select count(distinct plant_id) from costing.plant_capacity_profile),
  'by_effective_from', (select jsonb_object_agg(coalesce(effective_from::text,'null'),n) from (select effective_from,count(*) n from costing.plant_capacity_profile group by 1) z),
  'provisional', (select jsonb_object_agg(is_provisional::text,n) from (select is_provisional,count(*) n from costing.plant_capacity_profile group by 1) z),
  'current_rows', (select count(*) from costing.plant_capacity_profile p where effective_to is null and not exists (select 1 from costing.plant_capacity_profile q where q.supersedes_id=p.id)),
  'current_null_effective', (select count(*) from costing.plant_capacity_profile p where effective_to is null and effective_capacity is null and not exists (select 1 from costing.plant_capacity_profile q where q.supersedes_id=p.id)),
  'current_by_evidence', (select jsonb_object_agg(coalesce(evidence_type,'null'),n) from (select evidence_type,count(*) n from costing.plant_capacity_profile p where effective_to is null and not exists (select 1 from costing.plant_capacity_profile q where q.supersedes_id=p.id) group by 1) z),
  'current_by_applicability', (select jsonb_object_agg(coalesce(applicability_class,'null'),n) from (select applicability_class,count(*) n from costing.plant_capacity_profile p where effective_to is null and not exists (select 1 from costing.plant_capacity_profile q where q.supersedes_id=p.id) group by 1) z),
  'readiness', (select jsonb_object_agg(readiness,n) from (select readiness,count(*) n from costing.v_plant_capacity_readiness group by 1) z),
  'readiness_rows', (select count(*) from costing.v_plant_capacity_readiness),
  'machine_41', (select jsonb_agg(jsonb_build_array(id,applicability_class,equipment_class_code,capacity_mode,charge_basis,physical_unit,rated_capacity,effective_capacity,evidence_type,evidence_reference,is_provisional,effective_from,effective_to,supersedes_id,change_reason,approval_reference) order by id) from costing.plant_capacity_profile where plant_id=41),
  'revision_rows', (select count(*) from costing.capacity_master_revision),
  'revision_by', (select jsonb_object_agg(entity||':'||action,n) from (select entity,action,count(*) n from costing.capacity_master_revision group by 1,2) z),
  'step_rules', (select jsonb_agg(jsonb_build_array(id,rule_code,resource_class_code,activity_id,activity_name_at_approval,resolution,equipment_class_code,policy_reference,effective_from,effective_to) order by id) from costing.route_step_capacity_rule),
  'fallback_policy', (select count(*) from costing.capacity_fallback_policy),
  'legacy_class_caps', (select count(*) from costing.route_equipment_load_capacity)),
'demand_objects', (select jsonb_agg(c.relname) from pg_class c where c.relnamespace='costing'::regnamespace and (c.relname like '%demand%' or c.relname like '%season%')),
'products_seasonal', (select jsonb_build_object('is_seasonal_true',count(*) filter (where is_seasonal),'with_profile',count(*) filter (where season_profile_id is not null),'total',count(*)) from public.products),
'internal_loaded_128', (select count(*) from costing.sku_internal_loaded_cost_snapshot where refresh_run_id=128),
'feed', (select jsonb_agg(jsonb_build_array(period_start,refresh_run_id,n,ik,ok) order by period_start) from (select period_start, refresh_run_id, count(*) n, count(*) filter (where ik_negative_margin) ik, count(*) filter (where ok_negative_margin) ok from costing.v_price_revision_feed_approved group by 1,2) f),
'feed_md5', (select md5(string_agg(f::text,'|' order by period_start, sku_id)) from costing.v_price_revision_feed_approved f),
'neg_oct', (select jsonb_agg(sku_id order by sku_id) from costing.v_price_revision_feed_approved where period_start='2026-10-01' and (ik_negative_margin or ok_negative_margin)),
'audit_rows', (select count(*) from costing.cost_period_governance_audit),
'auths', (select count(*) from costing.costing_period_refresh_authorization)
) as r
